  (
    'd9000001-0010-4000-8000-000000000001',
    'SAMHSA National Helpline',
    'Free confidential 24/7 treatment referral and information service for individuals and families facing mental health or substance use disorders. Provides referrals to local treatment facilities and community organizations in North Carolina and nationwide. Spanish-language support available through trained specialists for justice-involved individuals seeking SUD or mental health treatment after release.',
    'Servicio gratuito y confidencial 24/7 de referencia e información para personas y familias con trastornos de salud mental o uso de sustancias. Proporciona referencias a centros de tratamiento locales en Carolina del Norte y a nivel nacional. Soporte en español disponible para personas con antecedentes penales que buscan tratamiento después de la liberación.',
    'c1000001-0005-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
    NULL,
    NULL,
    '800-662-4357',
    'https://www.samhsa.gov/find-help/national-helpline',
