    'Open to anyone in the United States seeking substance use or mental health treatment information and referrals.',
    'Abierto a cualquier persona en Estados Unidos que busque información y referencias de tratamiento.',
    'TTY 800-487-4889; also use FindTreatment.gov to search North Carolina providers online.',
