  (
    'd9000001-0011-4000-8000-000000000001',
    'FindTreatment.gov — North Carolina Provider Search',
    'SAMHSA''s online treatment locator helping North Carolina residents find substance use and mental health treatment providers by location, service type, and payment options including Medicaid. Justice-involved individuals can search outpatient, residential, and MAT providers before or after release from NCDAC custody or county jails across all 100 counties.',
    'Localizador en línea de SAMHSA que ayuda a residentes de Carolina del Norte a encontrar proveedores de tratamiento de uso de sustancias y salud mental por ubicación, tipo de servicio y opciones de pago incluido Medicaid. Personas con antecedentes penales pueden buscar proveedores ambulatorios, residenciales y TMO antes o después de la liberación.',
    'c1000001-0005-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
    NULL,
    NULL,
    NULL,
    'https://findtreatment.gov',
    NULL,
    'Website 24/7',
