    'Abierto a cualquier persona que busque tratamiento; las reglas de admisión varían según el proveedor.',
    'Search findtreatment.gov by North Carolina county or city; filter for MAT, outpatient, or residential services.',
    'Busque en findtreatment.gov por condado o ciudad de Carolina del Norte; filtre por TMO, ambulatorio o residencial.',
    ARRAY[]::TEXT[],
