  -- source id: 12
  (
    'd9000001-0012-4000-8000-000000000001',
    'NC Division of Motor Vehicles — ID Services',
    'The North Carolina Division of Motor Vehicles issues state ID cards and driver''s licenses required for employment, housing, and benefits enrollment after release. Returning citizens can apply for a North Carolina ID at driver license offices statewide with proof of identity and residency. Not a vital records office—contact county Register of Deeds for birth certificates.',
    'La División de Vehículos Motorizados de Carolina del Norte emite tarjetas de identificación estatal y licencias de conducir necesarias para empleo, vivienda e inscripción en beneficios después de la liberación. Los ciudadanos que regresan pueden solicitar una identificación en oficinas de licencias con prueba de identidad y residencia. No es oficina de registros vitales.',
    'c1000001-0008-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1100 New Bern Avenue',
    '919-715-7000',
    'https://www.ncdot.gov/dmv',
    NULL,
    'Driver license office hours vary; check ncdot.gov/dmv',
    'North Carolina residents with required identity and residency documentation; fees apply for ID cards and licenses.',
    'Residentes de Carolina del Norte con documentación requerida de identidad y residencia; aplican tarifas para tarjetas de identificación.',
    'Find driver license offices at ncdot.gov/dmv/offices; bring certified birth certificate or passport plus proof of North Carolina residency.',
    'Encuentre oficinas en ncdot.gov/dmv/offices; traiga certificado de nacimiento o pasaporte más prueba de residencia.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['State ID card issuance', 'Driver''s license services', 'ID renewal', 'Driver license office locator'],
    ARRAY['statewide', 'id-documentation', 'DMV', 'drivers-license', 'reentry'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 13
  (
    'd9000001-0013-4000-8000-000000000001',
    'NC Vital Records — Birth & Death Certificates',
    'The North Carolina Vital Records office processes requests for birth and death certificates needed for state ID, Medicaid, and employment applications after release. Returning citizens can order certified copies online, by mail, or through county Register of Deeds offices with acceptable identification. Processing times vary—order early in reentry planning.',
    'La oficina de Registros Vitales de Carolina del Norte procesa solicitudes de certificados de nacimiento y defunción necesarios para identificación estatal, Medicaid y solicitudes de empleo después de la liberación. Los ciudadanos que regresan pueden ordenar copias certificadas en línea, por correo o a través de oficinas del Registro de Actos del condado.',
    'c1000001-0008-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '225 N. McDowell Street',
    '919-733-3000',
    'https://www.ncdhhs.gov/divisions/public-health/vital-records',
    NULL,
    'Monday–Friday, 8:00 a.m.–5:00 p.m. ET',
    'Individuals with legal right to request the record; acceptable ID required; fees apply per certificate.',
    'Personas con derecho legal a solicitar el registro; se requiere identificación aceptable; aplican tarifas por certificado.',
    'Order online at vitalrecords.nc.gov or call 919-733-3000; county Register of Deeds offices also issue birth certificates.',
    'Ordene en vitalrecords.nc.gov o llame al 919-733-3000; las oficinas del Registro de Actos del condado también emiten certificados.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Birth certificate orders', 'Death certificate orders', 'Online vital records requests', 'Certified copy processing'],
    ARRAY['statewide', 'id-documentation', 'vital-records', 'birth-certificate'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
  -- source id: 14
  (
    'd9000001-0014-4000-8000-000000000001',
    'NC Department of Military and Veterans Affairs — Statewide',
    'The North Carolina Department of Military and Veterans Affairs helps justice-involved veterans access VA benefits, disability claims, employment programs, and housing resources through county veterans service offices across all 100 counties. Veterans released from incarceration may qualify for VA health care, vocational rehabilitation, and veterans treatment court supports. Benefits navigation and advocacy—not emergency shelter.',
    'El Departamento de Asuntos Militares y de Veteranos de Carolina del Norte ayuda a veteranos con antecedentes penales a acceder a beneficios del VA, reclamaciones de discapacidad, programas de empleo y recursos de vivienda a través de oficinas de servicios para veteranos del condado en los 100 condados. Los veteranos liberados pueden calificar para atención médica del VA y tribunales de tratamiento para veteranos.',
    'c1000001-0014-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1315 Mail Service Center',
    '919-733-3851',
    'https://www.ncdva.nc.gov',
    NULL,
    'County offices Monday–Friday business hours',
    'Honorably discharged or qualifying North Carolina veterans and their dependents; service documentation required.',
    'Veteranos de Carolina del Norte con baja honorable o calificados y sus dependientes; se requiere documentación de servicio.',
    'Find your county veterans service office at ncdva.nc.gov; free benefits claims assistance at all 100 county offices.',
    'Encuentre su oficina de servicios para veteranos del condado en ncdva.nc.gov; asistencia gratuita con reclamaciones.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['VA benefits claims assistance', 'Disability claims navigation', 'Employment program referrals', 'Veterans treatment court support'],
    ARRAY['statewide', 'veterans', 'VA-benefits', 'reentry', 'justice-involved-veterans'],
    ARRAY['accepts_criminal_record'],
    false,
    'active'
  ),
