  (
    'd9000001-0015-4000-8000-000000000001',
    'NC Second Chance Alliance',
    'The NC Second Chance Alliance is a statewide coalition of service providers, faith communities, businesses, and community leaders advocating for fair-chance policies and connecting justice-involved North Carolinians to housing, employment, and legal resources. The alliance coordinates local reentry networks and policy advocacy—not direct emergency services at the state office.',
    'La Alianza de Segunda Oportunidad de NC es una coalición estatal de proveedores de servicios, comunidades de fe, empresas y líderes comunitarios que abogan por políticas de segunda oportunidad y conectan a carolinenses con antecedentes penales con recursos de vivienda, empleo y legales. La alianza coordina redes locales de reinserción, no servicios de emergencia directos.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '224 S. Dawson Street',
    NULL,
    'https://ncsecondchance.org',
    'info@ncsecondchance.org',
    'Contact for current hours',
    'Justice-involved North Carolina residents and community partners seeking reentry coalition connections and fair-chance policy information.',
    'Residentes de Carolina del Norte con antecedentes penales y aliados comunitarios que buscan conexiones con coaliciones de reinserción.',
    'Visit ncsecondchance.org for member organizations and local reentry partner directory; contact info@ncsecondchance.org for coalition information.',
    'Visite ncsecondchance.org para organizaciones miembros y directorio de aliados locales; contacte info@ncsecondchance.org.',
    ARRAY[]::TEXT[],
    'statewide',
