    'd9000001-0016-4000-8000-000000000001',
    'NC Justice Center — Fair Chance Employment Project',
    'The North Carolina Justice Center Fair Chance Employment Project advocates for policies and practices that expand job opportunities for people with criminal records and connects returning citizens to legal resources, benefits navigation, and workforce partners across North Carolina. Staff provide policy education and referral navigation—not direct cash assistance or emergency housing.',
    'El Proyecto de Empleo de Segunda Oportunidad del Centro de Justicia de Carolina del Norte aboga por políticas que expanden oportunidades laborales para personas con antecedentes penales y conecta a quienes regresan con recursos legales, navegación de beneficios y aliados de fuerza laboral. El personal ofrece educación de políticas y referencias, no asistencia en efectivo ni vivienda de emergencia.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
