    'Residentes de Carolina del Norte con antecedentes penales y defensores que buscan información sobre empleo de segunda oportunidad y referencias legales.',
    'Visit ncjustice.org for fair-chance resources; connects to Legal Aid of NC and local workforce partners.',
    'Visite ncjustice.org para recursos de segunda oportunidad; conecta con Legal Aid of NC y aliados de fuerza laboral.',
