    'd9000001-0017-4000-8000-000000000001',
    'Center for Community Transitions — Charlotte',
    'Center for Community Transitions is Charlotte''s leading reentry organization providing transitional housing, employment training, life skills, and family reunification services for justice-involved women and men returning to Mecklenburg County after incarceration. CCT operates residential and community-based programs with case management connecting participants to NCWorks, DSS benefits, and local employers. Direct services—not a statewide hotline.',
    'Center for Community Transitions es la principal organización de reinserción de Charlotte que ofrece vivienda transicional, capacitación laboral, habilidades para la vida y reunificación familiar para mujeres y hombres con antecedentes penales que regresan al condado Mecklenburg. CCT opera programas residenciales y comunitarios con manejo de casos conectando participantes con NCWorks, beneficios DSS y empleadores locales.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Mecklenburg',
    'Charlotte',
    '801 E. Fourth Street',
    '704-375-1722',
    'https://centerforcommunitytransitions.org',
    NULL,
    'Contact for program hours',
    'Justice-involved adults returning to Mecklenburg County; program-specific requirements for residential tracks.',
    'Adultos con antecedentes penales que regresan al condado Mecklenburg; requisitos específicos del programa para programas residenciales.',
    'Call 704-375-1722 for intake; programs include Charlotte''s only reentry-specific transitional housing for women.',
    'Llame al 704-375-1722 para admisión; programas incluyen la única vivienda transicional de reinserción para mujeres en Charlotte.',
    ARRAY['Mecklenburg'],
    'single',
    ARRAY['Transitional housing', 'Employment training', 'Life skills', 'Family reunification', 'Case management'],
