    'd9000001-0018-4000-8000-000000000001',
    'StepUp Ministry — Raleigh Reentry',
    'StepUp Ministry helps justice-involved and low-income adults in Wake County achieve stable employment and self-sufficiency through job readiness classes, one-on-one coaching, and supportive services including referrals to housing and benefits partners. Multiple Raleigh-area offices serve returning citizens from Wake County Jail and state custody with fair-chance employer connections. Direct coaching services—not emergency shelter.',
    'StepUp Ministry ayuda a adultos con antecedentes penales y de bajos ingresos en el condado Wake a lograr empleo estable y autosuficiencia mediante clases de preparación laboral, coaching individual y servicios de apoyo incluidas referencias a aliados de vivienda y beneficios. Múltiples oficinas en el área de Raleigh sirven a ciudadanos que regresan de la cárcel del condado Wake.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1012 Oberlin Road',
    '919-834-7634',
    'https://stepupministry.org',
    NULL,
    'Monday–Friday business hours; class schedules vary',
