    'Adultos de bajos ingresos del condado Wake incluidas personas con antecedentes penales que buscan empleo y estabilidad.',
    'Call 919-834-7634 for enrollment; connects to NCWorks Raleigh and Wake County reentry partners.',
    'Llame al 919-834-7634 para inscripción; conecta con NCWorks Raleigh y aliados de reinserción del condado Wake.',
    ARRAY['Wake'],
    'single',
