    'd9000001-0019-4000-8000-000000000001',
    'TROSA — Durham',
    'TROSA is a multi-year residential recovery program in Durham providing free housing, vocational training, counseling, and job placement for people with substance use disorders including justice-involved adults referred from courts, probation, and prisons across North Carolina. Participants live on campus while completing therapeutic programming and workforce development—not a short-term emergency shelter.',
    'TROSA es un programa residencial de recuperación de varios años en Durham que ofrece vivienda gratuita, capacitación vocacional, consejería y colocación laboral para personas con trastornos por uso de sustancias incluidos adultos con antecedentes penales referidos por tribunales, probatoria y prisiones. Los participantes viven en el campus mientras completan programación terapéutica.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Durham',
    'Durham',
    '1820 James Street',
    '919-956-8886',
    'https://www.trosainc.org',
    NULL,
    'Residential program; contact admissions for intake',
    'Adults with substance use disorders willing to commit to multi-year residential recovery; justice referrals accepted per program policy.',
    'Adultos con trastornos por uso de sustancias dispuestos a comprometerse con recuperación residencial de varios años; referencias de justicia aceptadas según política.',
    'Call 919-956-8886 for admissions; free program including housing, meals, and job training on Durham campus.',
    'Llame al 919-956-8886 para admisiones; programa gratuito incluyendo vivienda, comidas y capacitación laboral.',
    ARRAY['Durham'],
    'single',
