    'Healing Transitions es una comunidad de recuperación basada en pares en Raleigh que ofrece desintoxicación no médica, vivienda de recuperación residencial y programación de fuerza laboral para adultos sin hogar con trastornos por uso de sustancias incluidos ciudadanos que regresan de la cárcel del condado Wake. El campus proporciona comidas, manejo de casos y conexiones con NCWorks.',
