    'Urban Ministries of Wake County opera la Clínica Open Door y programas de asistencia en crisis sirviendo a residentes del condado Wake sin seguro y de bajos ingresos incluidos ciudadanos que regresan que necesitan atención primaria, asistencia con recetas y apoyo alimentario de emergencia. La clínica ofrece atención médica con tarifa móvil y conecta pacientes con beneficios DSS.',
