    'Good Shepherd Center en Wilmington proporciona refugio de emergencia, comidas, manejo de casos y navegación de recursos de reinserción para adultos sin hogar en el condado New Hanover incluidos ciudadanos que regresan recién liberados de la cárcel local o custodia estatal. Servicios directos incluyen acceso a refugio diurno y conexiones con aliados de vivienda y empleo.',
