  (
    'd9000001-0023-4000-8000-000000000001',
    'NCDAC Division of Community Supervision — Statewide',
    'The North Carolina Department of Adult Correction Division of Community Supervision provides probation, parole, and post-release supervision for more than 84,000 justice-involved adults across all 100 counties. More than 2,000 certified officers staff 273 field offices, connecting returning citizens to local reentry partners for housing, employment, treatment, and compliance reporting. Contact your assigned officer—not a walk-in benefits or emergency housing center.',
    'La División de Supervisión Comunitaria del Departamento de Corrección para Adultos de Carolina del Norte brinda libertad condicional, probatoria y supervisión posterior a la liberación a más de 84.000 adultos en los 100 condados. Más de 2.000 oficiales certificados conectan a quienes regresan con aliados locales para vivienda, empleo y tratamiento. Contacte a su oficial asignado; no es un centro de beneficios ni de vivienda de emergencia.',
    'c1000001-0016-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '2020 Yonkers Road',
    '919-716-3100',
    'https://www.dac.nc.gov/divisions-and-sections/community-supervision',
    NULL,
    'Field offices typically Monday–Friday business hours',
    'Adults under NCDAC probation, parole, or post-release supervision in North Carolina; report to assigned community supervision officer.',
    'Adultos bajo supervisión probatoria, libertad condicional o post-liberación de NCDAC en Carolina del Norte; reporte al oficial asignado.',
    'Find local offices at dac.nc.gov community supervision directory; statewide hotline 919-716-3100 for division information.',
    'Encuentre oficinas locales en el directorio de supervisión comunitaria de dac.nc.gov; línea estatal 919-716-3100.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Probation supervision', 'Parole supervision', 'Post-release supervision', 'Compliance reporting', 'Reentry resource referrals'],
    ARRAY['statewide', 'probation-parole', 'NCDAC', 'community-supervision', 'reentry'],
    ARRAY[]::TEXT[],
    false,
    'active'
