    'd9000001-0029-4000-8000-000000000001',
    'NCDAC Community Supervision — Cumberland Judicial District 12',
    'NCDAC Judicial District 12 provides probation and post-release supervision for Cumberland County from the Fayetteville West Russell Street office near Fort Liberty. Officers connect returning citizens to Fayetteville-Cumberland Reentry Council, SouthLight Cumberland services, NCWorks Fayetteville, and Cumberland County Veterans Service Office. Supervision reporting is through assigned officers only.',
    'El Distrito Judicial 12 de NCDAC brinda supervisión probatoria y post-liberación para el condado Cumberland desde la oficina de Fayetteville. Los oficiales conectan a quienes regresan con el Consejo de Reinserción de Fayetteville-Cumberland, SouthLight y NCWorks. Los reportes de supervisión son solo a través del oficial asignado.',
