    'NCDAC Community Supervision — New Hanover Judicial District 5',
    'NCDAC Judicial District 5 supervises probationers and parolees in New Hanover and Pender counties from the Wilmington Market Street office. Officers coordinate compliance reporting and referrals to New Hanover Local Reentry Council, StepUp Wilmington, Food Bank of Central and Eastern NC Wilmington branch, and county veterans services. Contact your assigned officer—not emergency shelter intake.',
    'El Distrito Judicial 5 de NCDAC supervisa personas en libertad probatoria y condicional en los condados New Hanover y Pender desde la oficina de Wilmington. Los oficiales coordinan reportes de cumplimiento y referencias al Consejo Local de Reinserción de New Hanover, StepUp Wilmington y servicios para veteranos del condado. Contacte a su oficial asignado.',
