  (
    'd9000001-0031-4000-8000-000000000001',
    'NCDAC Division of Rehabilitation and Reentry Services',
    'The NCDAC Division of Rehabilitation and Reentry oversees evidence-based prison programming, transition services, local reentry council funding, and statewide reentry partnerships aimed at reducing recidivism. Staff coordinate pre-release planning, transitional housing oversight, and the Reentry 2030 initiative connecting returning citizens to housing, employment, and treatment across North Carolina. A policy and coordination division—not direct emergency cash or shelter intake.',
    'La División de Rehabilitación y Reinserción de NCDAC supervisa programación carcelaria basada en evidencia, servicios de transición, financiamiento de consejos locales de reinserción y alianzas estatales para reducir la reincidencia. El personal coordina planificación previa a la liberación, vivienda transicional e iniciativa Reentry 2030. Es una división de política y coordinación, no admisión directa a refugio o efectivo de emergencia.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '2020 Yonkers Road',
    '919-733-2650',
    'https://www.dac.nc.gov/divisions-and-sections/rehabilitation-and-reentry-services',
    NULL,
    'State office Monday–Friday business hours',
    'Justice-involved adults in NCDAC custody or recently released; community partners seeking NCDAC reentry engagement.',
    'Adultos en custodia de NCDAC o recién liberados; aliados comunitarios que buscan vincularse con reinserción de NCDAC.',
    'Visit dac.nc.gov rehabilitation and reentry; local reentry council contacts at dac.nc.gov/local-reentry-councils.',
    'Visite dac.nc.gov rehabilitación y reinserción; contactos de consejos locales en dac.nc.gov/local-reentry-councils.',
