  (
    'd9000001-0032-4000-8000-000000000001',
    'North Carolina Justice Center — Fair Chance Criminal Justice Project',
    'The NC Justice Center Fair Chance Criminal Justice Project partners with impacted people, congregations, and advocacy organizations to change criminal legal system policies from arrest through reentry. Staff advance Second Chance Act implementation, fair-chance hiring reforms, and community education while serving as backbone support for the NC Second Chance Alliance. Policy advocacy and coalition work—not individual legal intake or emergency cash assistance.',
    'El Proyecto de Justicia Penal de Oportunidad Justa del Centro de Justicia de NC colabora con personas afectadas, congregaciones y organizaciones de defensa para cambiar políticas del sistema legal penal desde el arresto hasta la reinserción. El personal impulsa la Ley de Segunda Oportunidad y reformas de contratación justa. Es defensa de políticas y trabajo de coalición, no admisión legal individual ni efectivo de emergencia.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    'P.O. Box 28068',
    '919-856-2570',
    'https://www.ncjustice.org/projects/fair-chance-criminal-justice-project/',
    'ncjc-fccj@ncjustice.org',
    'Monday–Friday business hours',
    'Community members and partners seeking criminal justice policy reform and reentry advocacy in North Carolina.',
    'Miembros de la comunidad y aliados que buscan reforma de políticas de justicia penal y defensa de reinserción en Carolina del Norte.',
    'Email ncjc-fccj@ncjustice.org; NCJC does not provide individual legal advice through this project.',
    'Correo ncjc-fccj@ncjustice.org; NCJC no brinda asesoría legal individual a través de este proyecto.',
    ARRAY[]::TEXT[],
    'statewide',
