  (
    'd9000001-0033-4000-8000-000000000001',
    'Center for Community Transitions (CCT)',
    'Center for Community Transitions is a Charlotte nonprofit founded in 1974 that helps people with criminal records and their families rebuild through reentry coaching, employment readiness, and family support programs. LifeWorks! at the Goodwill Opportunity Campus provides job training and placement for justice-involved adults, while Families Doing Time supports children and caregivers during incarceration. Referral-based programs—not emergency shelter or cash assistance.',
    'Center for Community Transitions es una organización sin fines de lucro de Charlotte fundada en 1974 que ayuda a personas con antecedentes penales y sus familias a reconstruirse mediante coaching de reinserción, preparación laboral y apoyo familiar. LifeWorks! ofrece capacitación y colocación laboral; Families Doing Time apoya a niños y cuidadores durante la encarcelación. Programas con referencia, no refugio de emergencia ni efectivo.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Mecklenburg',
    'Charlotte',
    '5825 Old Concord Road',
    '704-494-0001',
    'https://centerforcommunitytransitions.org/',
    NULL,
    'Contact for program hours',
    'Mecklenburg-area adults with criminal records and their families; program-specific eligibility applies per service.',
    'Adultos del área de Mecklenburg con antecedentes penales y sus familias; aplican requisitos específicos por servicio.',
    'LifeWorks! at 5301 Wilkinson Blvd, phone 704-374-0762; main office 704-494-0001.',
    'LifeWorks! en 5301 Wilkinson Blvd, teléfono 704-374-0762; oficina principal 704-494-0001.',
