  (
    'd9000001-0034-4000-8000-000000000001',
    'Crossroads Reentry Ministries',
    'Crossroads Reentry Ministries provides pre-release classroom instruction and post-release coaching for jail and prison inmates returning to the Charlotte region, including vocational training, sober living referrals, job placement, and case management. The program works inside Mecklenburg detention facilities and continues support after release through a Huntersville-based team. Call for intake—not a walk-in emergency shelter.',
    'Crossroads Reentry Ministries ofrece instrucción en el aula antes de la liberación y coaching posterior para personas que regresan a la región de Charlotte, incluyendo capacitación vocacional, referencias de vivienda sobria, colocación laboral y manejo de casos. Trabaja dentro de centros de detención de Mecklenburg y continúa el apoyo después de la liberación. Llame para admisión; no es refugio de emergencia sin cita.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Mecklenburg',
    'Huntersville',
    '12411 Cool Mist Lane',
    '704-499-1332',
    'https://www.crossroadsreentry.org/',
