    'Adultos con antecedentes penales en instalaciones correccionales del área de Mecklenburg o recién liberados; llame para evaluación.',
    'Leave a message at 704-499-1332; return call within one business day.',
    'Deje un mensaje al 704-499-1332; devolución de llamada en un día hábil.',
