  (
    'd9000001-0035-4000-8000-000000000001',
    'Oak City Cares — Wake County Coordinated Entry Hub',
    'Oak City Cares is a downtown Raleigh hub coordinating homelessness services for Wake County, serving as a Coordinated Entry access site for shelter referrals, street outreach, and homelessness prevention navigation. Care coordinators meet walk-in guests Monday through Friday to assess housing crises and connect individuals—including returning citizens—to Urban Ministries and Healing Transitions. In-person access site—not phone intake for CE assessments.',
    'Oak City Cares es un centro en el centro de Raleigh que coordina servicios para personas sin hogar en el condado Wake, sirviendo como sitio de acceso de Entrada Coordinada para referencias a refugios y prevención de la falta de vivienda. Los coordinadores atienden sin cita de lunes a viernes y conectan a personas, incluidos quienes regresan de la encarcelación, con Urban Ministries y Healing Transitions. Sitio de acceso en persona, no evaluación telefónica.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1430 South Wilmington Street',
    '984-344-9607',
    'https://oakcitycares.org/',
    'kathy.johnson@oakcitycares.org',
    'Monday–Friday 9:00 a.m.–3:00 p.m.; Wednesday until 1:00 p.m.',
    'Wake County residents experiencing homelessness or housing crisis; walk-in Monday–Friday 9:00 a.m.–3:00 p.m. (Wednesdays end 1:00 p.m.).',
    'Residentes del condado Wake en crisis de vivienda; sin cita lunes a viernes 9:00 a.m.–3:00 p.m. (miércoles hasta 1:00 p.m.).',
    'Coordinated Entry access site; download CE flyer at wakenc507.org for additional access sites.',
    'Sitio de acceso de Entrada Coordinada; descargue el folleto CE en wakenc507.org.',
