  (
    'd9000001-0036-4000-8000-000000000001',
    'Mecklenburg Reentry Partners Network',
    'The Mecklenburg Reentry Partners Network is the county''s NCDAC-funded local reentry council connecting justice-involved adults to housing, employment, transportation, ID restoration, and behavioral health resources across Charlotte and Mecklenburg County. Network staff coordinate referrals among CCT, Crossroads, NCWorks, and community providers to reduce recidivism. A navigation and referral hub—not direct emergency cash or shelter beds.',
    'La Red de Aliados de Reinserción de Mecklenburg es el consejo local de reinserción financiado por NCDAC que conecta a adultos con antecedentes penales con vivienda, empleo, transporte, restauración de identificación y salud conductual en Charlotte. El personal coordina referencias entre CCT, Crossroads y NCWorks para reducir la reincidencia. Es un centro de navegación y referencias, no camas de refugio ni efectivo de emergencia.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Mecklenburg',
    'Charlotte',
