  (
    'd9000001-0037-4000-8000-000000000001',
    'Wake Local Reentry Council',
    'The Wake Local Reentry Council is an NCDAC-funded coalition connecting justice-involved adults in Wake County to housing, employment, transportation, substance use treatment, and documentation assistance through community partners including StepUp Ministry, Healing Transitions, Oak City Cares, and NC FIT. Council navigators help returning citizens build reentry plans after prison or jail release. A referral and coordination body—not emergency shelter intake.',
    'El Consejo Local de Reinserción de Wake es una coalición financiada por NCDAC que conecta a adultos con antecedentes penales en el condado Wake con vivienda, empleo, transporte, tratamiento de sustancias y asistencia documental a través de aliados como StepUp Ministry, Healing Transitions y Oak City Cares. Los navegadores ayudan a elaborar planes de reinserción. Cuerpo de referencia y coordinación, no admisión a refugio de emergencia.',
    'c1000001-0017-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
