  (
    'd9000001-0038-4000-8000-000000000001',
    'Durham Local Reentry Council',
    'The Durham Local Reentry Council coordinates reentry services for justice-involved adults returning to Durham County through partnerships with Durham County Justice Services, Lincoln Community Health Center, TROSA, and NC FIT. NCDAC-funded navigators connect returning citizens to housing, employment, behavioral health, and ID resources while supporting the county''s reentry strategic plan. Referral-based coordination—not a walk-in crisis line.',
    'El Consejo Local de Reinserción de Durham coordina servicios para adultos con antecedentes penales que regresan al condado Durham mediante alianzas con Servicios de Justicia del condado, Lincoln Community Health Center, TROSA y NC FIT. Los navegadores financiados por NCDAC conectan con vivienda, empleo, salud conductual e identificación. Coordinación con referencia, no línea de crisis sin cita.',
    'c1000001-0017-4000-8000-000000000001',
