  (
    'd9000001-0039-4000-8000-000000000001',
    'Healing Transitions — Men''s Campus Recovery Housing',
    'Healing Transitions operates a peer-based long-term recovery program and emergency drop-in shelter for men in Wake County struggling with addiction, including uninsured and justice-involved residents. The men''s campus on Goode Street provides non-medical detox entry, a motivation track with guaranteed beds, and employment-focused recovery tracks at no cost for Wake County citizens age 18 and older. Open 24/7 for shelter and detox—not a general reentry-only program without substance use needs.',
    'Healing Transitions opera un programa de recuperación a largo plazo basado en pares y refugio de emergencia para hombres en el condado Wake que luchan con adicción, incluidos residentes sin seguro y con antecedentes penales. El campus de hombres en Goode Street ofrece entrada a desintoxicación no médica y pistas de recuperación enfocadas en empleo sin costo para ciudadanos del condado Wake mayores de 18 años. Abierto 24/7 para refugio y desintoxicación.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1251 Goode Street',
    '919-838-9800',
    'https://healing-transitions.org/',
    NULL,
    '24 hours daily for shelter and detox',
    'Wake County men age 18+ with substance use disorder; detox line 919-838-9848; no insurance required.',
    'Hombres del condado Wake mayores de 18 años con trastorno por uso de sustancias; línea de desintoxicación 919-838-9848; no se requiere seguro.',
    'Men''s detox 919-838-9848; women''s campus 3304 Glen Royal Rd; program is free for Wake County residents.',
    'Desintoxicación para hombres 919-838-9848; campus de mujeres 3304 Glen Royal Rd; programa gratuito para residentes de Wake.',
    ARRAY['Wake'],
    'single',
