  (
    'd9000001-0040-4000-8000-000000000001',
    'Healing Transitions — Women''s Campus Recovery Housing',
    'Healing Transitions women''s campus on Glen Royal Road provides long-term peer-based recovery housing, non-medical detox, and emergency shelter for women in Wake County including justice-involved residents rebuilding stability after incarceration and addiction. The program offers motivation and engagement tracks, longer-term shelter beds, and employment-focused transition planning at no cost for eligible Wake County women. Detox intake via 919-865-2558—not a domestic violence shelter.',
    'El campus de mujeres de Healing Transitions en Glen Royal Road ofrece vivienda de recuperación a largo plazo basada en pares, desintoxicación no médica y refugio de emergencia para mujeres en el condado Wake, incluidas residentes con antecedentes penales que reconstruyen estabilidad. El programa ofrece pistas de motivación, camas de refugio a largo plazo y planificación de transición laboral sin costo. Admisión de desintoxicación vía 919-865-2558.',
