  (
    'd9000001-0041-4000-8000-000000000001',
    'Urban Ministries of Wake County — Helen Wright Center for Women',
    'Urban Ministries of Wake County operates the Helen Wright Center for Women, the only low-barrier facility in Wake County serving single adult women without custody of children who are experiencing homelessness. The center provides 24/7 shelter, meals, workforce development, and goal-oriented case management to move women from homelessness to stable housing. Intake is through Wake County Coordinated Entry—not a walk-in drop-in shelter.',
    'Urban Ministries of Wake County opera el Helen Wright Center for Women, la única instalación de baja barrera en el condado Wake para mujeres adultas solteras sin custodia de hijos que enfrentan falta de vivienda. El centro ofrece refugio 24/7, comidas, desarrollo laboral y manejo de casos orientado a metas. La admisión es a través de la Entrada Coordinada del condado Wake, no es refugio sin cita.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '3603 Bastion Lane',
    '919-833-1748',
    'https://www.urbanmin.org/services/shelter',
    NULL,
    '24 hours daily once admitted',
    'Single adult women without children in custody experiencing homelessness in Wake County; Coordinated Entry referral required.',
    'Mujeres adultas solteras sin hijos bajo custodia sin hogar en el condado Wake; se requiere referencia de Entrada Coordinada.',
    'Not a drop-in shelter; access via Oak City Cares or other CE sites; general line 919-833-1748.',
    'No es refugio sin cita; acceso vía Oak City Cares u otros sitios CE; línea general 919-833-1748.',
    ARRAY['Wake'],
