  -- source id: 42
  (
    'd9000001-0042-4000-8000-000000000001',
    'Charlotte Rescue Mission — Rebound Men''s Recovery Program',
    'Charlotte Rescue Mission Rebound provides free faith-based residential addiction recovery for men who cannot afford private treatment, including justice-involved men seeking sobriety, employment, and stable housing after release. The 12-step based program combines clinical substance abuse counseling with Christian context and connects graduates to Recovery Living transitional housing for up to two years. Men must call 704-333-HOPE ext. 501 themselves for telephone screening.',
    'Charlotte Rescue Mission Rebound ofrece recuperación residencial gratuita basada en la fe para hombres que no pueden pagar tratamiento privado, incluidos hombres con antecedentes penales que buscan sobriedad, empleo y vivienda estable. El programa combina consejería clínica con contexto cristiano y conecta graduados con vivienda transicional Recovery Living hasta por dos años. Los hombres deben llamar al 704-333-HOPE ext. 501 para evaluación telefónica.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Mecklenburg',
    'Charlotte',
    '1515 East 7th Street',
