    'Charlotte Rescue Mission — Recovery Living Transitional Housing',
    'Charlotte Rescue Mission Recovery Living offers up to two years of transitional housing for graduates of Rebound and Dove Nest recovery programs who need additional time to secure employment and permanent housing in Charlotte. Residents participate in life skills training at Community Matters Café or live in supervised recovery residences while maintaining sobriety and employment goals. Graduates of core programs only—not open walk-in intake.',
    'Charlotte Rescue Mission Recovery Living ofrece hasta dos años de vivienda transicional para graduados de los programas Rebound y Dove Nest que necesitan tiempo adicional para conseguir empleo y vivienda permanente en Charlotte. Los residentes participan en capacitación de habilidades para la vida o viven en residencias de recuperación supervisadas. Solo graduados de programas principales, no admisión sin cita.',
