    'd9000001-0044-4000-8000-000000000001',
    'TROSA — Durham Residential Recovery Campus',
    'TROSA is a state-licensed, multi-year voluntary residential substance use disorder treatment program in Durham serving men and women at no charge, including justice-involved residents referred by courts and probation officers. The comprehensive campus provides housing, meals, behavioral therapy, vocational training, medical care, and reentry support with strong post-graduation employment and recidivism outcomes. Call admissions at 919-419-1059—no referral required.',
    'TROSA es un programa voluntario residencial de varios años con licencia estatal para trastornos por uso de sustancias en Durham que atiende a hombres y mujeres sin costo, incluidos residentes con antecedentes penales referidos por tribunales. El campus integral ofrece vivienda, comidas, terapia conductual, capacitación vocacional, atención médica y apoyo de reinserción. Llame a admisiones al 919-419-1059; no se requiere referencia.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Durham',
    'Durham',
    '1820 James Street',
    '919-419-1059',
    'https://trosainc.org/',
