    'Admissions Monday–Friday business hours',
    'Adults with substance use disorder seeking long-term residential treatment; telephone interview required; incarcerated applicants may write to admissions address.',
    'Adultos con trastorno por uso de sustancias que buscan tratamiento residencial a largo plazo; se requiere entrevista telefónica; solicitantes encarcelados pueden escribir a la dirección de admisiones.',
    'Toll-free 833-408-7672; Winston-Salem campus also available; mail letters to 1820 James Street Durham NC 27707.',
    'Línea gratuita 833-408-7672; campus de Winston-Salem también disponible; cartas a 1820 James Street Durham NC 27707.',
