    'd9000001-0045-4000-8000-000000000001',
    'TROSA — Winston-Salem Residential Recovery Campus',
    'TROSA''s Winston-Salem campus extends the Durham-based multi-year residential substance use disorder treatment model to the Piedmont Triad, providing free housing, vocational training, behavioral therapy, and comprehensive reentry support for men and women including justice-involved participants. The evidence-based program emphasizes peer accountability and has documented low recidivism among graduates. Contact TROSA Admissions at 919-419-1059 or toll-free 833-408-7672.',
    'El campus de TROSA en Winston-Salem extiende el modelo de tratamiento residencial de varios años de Durham al Piedmont Triad, ofreciendo vivienda gratuita, capacitación vocacional, terapia conductual y apoyo integral de reinserción para hombres y mujeres, incluidos participantes con antecedentes penales. Contacte admisiones al 919-419-1059 o 833-408-7672.',
