    'd9000001-0046-4000-8000-000000000001',
    'Oxford House of North Carolina — Recovery Residences',
    'Oxford House of North Carolina operates democratic self-run sober living homes across Charlotte, Raleigh, Durham, Greensboro, and other NC communities, providing affordable recovery housing for individuals in early sobriety including justice-involved residents transitioning from treatment or incarceration. Houses are gender-specific with peer accountability and weekly self-pay fees. Use the Oxford House directory to find bed openings by city—not an emergency shelter.',
    'Oxford House of Carolina del Norte opera hogares de vida sobria autogestionados democráticamente en Charlotte, Raleigh, Durham, Greensboro y otras comunidades, con vivienda de recuperación asequible para personas en sobriedad temprana, incluidos residentes con antecedentes penales en transición. Las casas son por género con responsabilidad entre pares y tarifas semanales de autocobro. Use el directorio de Oxford House para encontrar vacantes por ciudad.',
