    'Crisis Assistance Ministry helps Mecklenburg County families facing eviction, utility disconnection, or clothing needs through financial assistance, a free store, and resource navigation for low-income households including returning citizens rebuilding after incarceration. The organization partners with Charlotte reentry providers to stabilize housing while residents seek employment. Appointment and documentation required—not a walk-in shelter.',
    'Crisis Assistance Ministry ayuda a familias del condado Mecklenburg que enfrentan desalojo, corte de servicios públicos o necesidades de ropa mediante asistencia financiera, tienda gratuita y navegación de recursos para hogares de bajos ingresos, incluidos quienes regresan de la encarcelación. Se requiere cita y documentación; no es refugio sin cita.',
