    'Guilford County Local Reentry Council',
    'The Guilford County Local Reentry Council is an NCDAC-funded coalition housed with StepUp Greensboro that connects justice-involved adults in Greensboro and High Point to housing, employment, transportation, and behavioral health resources. Navigators coordinate referrals among Goodwill Northwest NC, Greensboro Urban Ministry, and NCWorks partners to support successful community reintegration. Referral-based coordination—not emergency shelter.',
    'El Consejo Local de Reinserción del condado Guilford es una coalición financiada por NCDAC con StepUp Greensboro que conecta a adultos con antecedentes penales en Greensboro y High Point con vivienda, empleo, transporte y salud conductual. Los navegadores coordinan referencias entre Goodwill, Greensboro Urban Ministry y NCWorks. Coordinación con referencia, no refugio de emergencia.',
