    'The Forsyth County Reentry Council connects justice-involved adults in Winston-Salem to housing, employment, substance use treatment, and documentation assistance through partnerships with Goodwill Northwest NC, Piedmont Triad Regional Council, and TROSA. NCDAC-funded navigators help returning citizens build comprehensive reentry plans and access Triad community resources. A referral hub—not direct emergency services.',
