    'El Consejo de Reinserción de Fayetteville-Cumberland es la coalición local financiada por NCDAC que sirve al condado Cumberland, incluida la comunidad de Fort Liberty, conectando a quienes regresan con SouthLight, NCWorks y servicios para veteranos. El personal coordina referencias de empleo, salud conductual y restauración de identificación. Coordinación de referencias, no centro de crisis sin cita.',
