    'El Consejo Local de Reinserción de New Hanover conecta a adultos con antecedentes penales que regresan a Wilmington con vivienda, empleo, transporte y recursos de sustancias mediante LINC y aliados comunitarios. Navegadores financiados por NCDAC coordinan con StepUp Wilmington y el banco de alimentos. Basado en referencias, no efectivo de emergencia ni refugio.',
