    'd9000001-0052-4000-8000-000000000001',
    'StepUp Ministry — Raleigh Employment Academy',
    'StepUp Ministry in Raleigh provides a weeklong Employment Academy and yearlong life skills coaching to help unemployed adults—including most participants with criminal backgrounds—build resumes, interview skills, and employer connections across Wake County. The Jobs Team partners with fair-chance employers for placement while offering image consultation, financial literacy, and alumni support. Applicants need 30 days substance-free status and valid photo ID.',
    'StepUp Ministry en Raleigh ofrece una Academia de Empleo de una semana y coaching de habilidades para la vida durante un año para ayudar a adultos desempleados, incluida la mayoría con antecedentes penales, a crear currículos, habilidades de entrevista y conexiones con empleadores en el condado Wake. Los solicitantes necesitan 30 días libres de sustancias e identificación con foto.',
    'c1000001-0003-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1701 Oberlin Road',
    '919-781-0156',
    'https://www.stepupministry.org/',
