    'Working-age adults free from substance use 30 days; no pending criminal charges; valid photo ID and Social Security card required.',
    'Adultos en edad laboral libres de sustancias 30 días; sin cargos penales pendientes; se requiere identificación con foto y tarjeta de Seguro Social.',
    'Apply at stepupministry.org/get-help; office Mon–Thu 8:30–5, Fri 8:30–2:30.',
