    'StepUp Ministry — Durham Office',
    'StepUp Durham extends the StepUp Ministry employment model to justice-involved and long-term unemployed adults in Durham County through job readiness workshops, case management, and partnerships with fair-chance Triangle employers. Participants complete the weeklong Employment Academy curriculum with localized employer networking and compassionate accountability from Durham staff at West Knox Street.',
    'StepUp Durham extiende el modelo de empleo de StepUp Ministry a adultos desempleados de largo plazo y con antecedentes penales en el condado Durham mediante talleres de preparación laboral, manejo de casos y alianzas con empleadores de segunda oportunidad del Triángulo en West Knox Street.',
