  (
    'd9000001-0055-4000-8000-000000000001',
    'StepUp Ministry — Wilmington Office',
    'StepUp Ministry — Wilmington Office serves justice-involved adults and families rebuilding stability after incarceration in New Hanover County. StepUp Wilmington brings fair-chance employment training to New Hanover County, helping justice-involved and long-term unemployed coastal NC residents build job readiness, employer connections, and financial stability through the StepUp Employment Academy model with localized case management and Wilmington-area business partnerships. Staff help justice-involved job seekers build work history, remove record-related barriers, and connect to fair-chance employers in the region. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'StepUp Ministry — Wilmington Office sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de New Hanover. El personal ayuda a quienes buscan empleo con antecedentes penales a construir historial laboral, reducir barreras por antecedentes y conectarse con empleadores de segunda oportunidad. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
