    'La División de Empleo e Independencia para Personas con Discapacidades de NC ayuda a carolinenses con discapacidades a prepararse, obtener y mantener empleo mediante consejería, capacitación y alianzas con empleadores. Clientes con antecedentes penales y discapacidades calificadas pueden acceder a evaluación vocacional y empleo apoyado. Llame al 800-689-9090.',
