  (
    'd9000001-0073-4000-8000-000000000001',
    'NC FIT Program — Wake County',
    'The NC Formerly Incarcerated Transition Program in Wake County connects people released within two years who have chronic medical conditions, mental illness, or substance use disorders to primary care and reentry planning through community health workers with lived experience of incarceration at UNC REACH with partners Advance Community Health and Oak City Cares.',
    'El Programa NC FIT en el condado Wake conecta a personas liberadas en dos años con condiciones médicas crónicas, enfermedad mental o trastornos por uso de sustancias con atención primaria y planificación de reinserción mediante trabajadores de salud comunitaria con experiencia de encarcelación en UNC REACH.',
