    'd9000001-0075-4000-8000-000000000001',
    'Alliance Health — Wake/Durham/Johnston LME/MCO',
    'Alliance Health — Wake/Durham/Johnston LME/MCO serves justice-involved adults and families rebuilding stability after incarceration in Wake, Durham, and Johnston counties. Alliance Health manages public behavioral health and intellectual/developmental disability services in Wake, Durham, and Johnston counties, connecting Medicaid beneficiaries and uninsured residents to mental health, substance use, and crisis services including peer support for justice-involved adults rebuilding stability after release. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Alliance Health — Wake/Durham/Johnston LME/MCO sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en los condados Wake, Durham y Johnston. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0004-4000-8000-000000000001',
    'North Carolina',
    'Wake',
