    'SouthLight Healthcare ofrece tratamiento de trastornos por uso de sustancias, consejería de salud mental, tratamiento de opioides en consultorio y manejo psiquiátrico en los condados Wake, Durham, Johnston, Wilson, Cumberland y Harnett. Clientes con antecedentes penales acceden a programas ambulatorios intensivos y apoyo entre pares.',
