    'Trillium Health Resources — Eastern NC LME/MCO',
    'Trillium Health Resources — Eastern NC LME/MCO serves justice-involved adults and families rebuilding stability after incarceration in 5 North Carolina counties. Trillium Health Resources manages public behavioral health services for 26 eastern NC counties including New Hanover, Brunswick, and Pender, connecting residents to mental health, substance use, and crisis care. Returning citizens in coastal NC access peer support and treatment through Trillium provider networks. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Trillium Health Resources — Eastern NC LME/MCO sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en 5 condados de Carolina del Norte. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
