    'd9000001-0084-4000-8000-000000000001',
    'NC Department of Military and Veterans Affairs — Benefits Hotline',
    'The NC Department of Military and Veterans Affairs helps veterans and their families access federal, state, and local veterans benefits through state service centers, county Veterans Service Officers, and the NC4VETS hotline. DMVA benefits specialists assist with disability claims, education benefits, and healthcare enrollment for justice-involved veterans returning to North Carolina communities.',
    'El Departamento de Asuntos Militares y de Veteranos de NC ayuda a veteranos y sus familias a acceder a beneficios federales, estatales y locales mediante centros estatales, Oficiales de Servicios para Veteranos del condado y la línea NC4VETS. Especialistas ayudan con reclamaciones de discapacidad, beneficios educativos e inscripción en atención médica para veteranos con antecedentes penales.',
