    'd9000001-0090-4000-8000-000000000001',
    'Second Harvest Food Bank of Metrolina',
    'Second Harvest Food Bank of Metrolina collects and distributes food to nearly 650 hunger-relief agencies across 19 NC and SC counties including Mecklenburg, Gaston, and Cabarrus, serving returning citizens through partner pantries, mobile distributions, and SNAP outreach. The Charlotte warehouse on Spratt Street coordinates regional food access—not direct walk-in pantry for individuals.',
