  (
    'd9000001-0091-4000-8000-000000000001',
    'Food Bank of Central & Eastern North Carolina — Raleigh Branch',
    'Food Bank of Central & Eastern North Carolina — Raleigh Branch serves justice-involved adults and families rebuilding stability after incarceration in 5 North Carolina counties. The Food Bank of Central and Eastern North Carolina Raleigh branch on Capital Boulevard distributes food to partner agencies across 34 counties including Wake, Durham, and Johnston, connecting returning citizens to local pantries, mobile distributions, and SNAP application assistance through the regional hunger-relief network. Food assistance does not usually require a criminal-record disclosure; staff can help with SNAP applications and pantry locations by ZIP code. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Food Bank of Central & Eastern North Carolina — Raleigh Branch sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en 5 condados de Carolina del Norte. La asistencia alimentaria generalmente no requiere declarar antecedentes penales; el personal puede ayudar con solicitudes SNAP y ubicaciones de despensas por código postal. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0007-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '1924 Capital Boulevard',
    '919-875-0707',
    'https://foodbankcenc.org/',
    'communication@foodbankcenc.org',
    'Monday–Friday 8:30 a.m.–4:00 p.m.',
    'Access food through partner agencies; find pantry locator on foodbankcenc.org.',
    'Acceda a alimentos a través de agencias aliadas; localizador de despensas en foodbankcenc.org.',
    'Mon–Fri 8:30–4; Durham branch 919-956-2513.',
    'Lun–vie 8:30–4; sucursal Durham 919-956-2513.',
