    'd9000001-0092-4000-8000-000000000001',
    'Nourish Up — Charlotte Food Pantry Network',
    'Nourish Up (formerly Loaves & Fishes/Friendship Trays) operates the largest network of food pantries in North Carolina, providing groceries, home delivery, and Meals on Wheels for Mecklenburg County neighbors in need including returning citizens rebuilding food security after incarceration. Referral may be required for some pantry locations.',
    'Nourish Up (anteriormente Loaves & Fishes/Friendship Trays) opera la red de despensas de alimentos más grande de Carolina del Norte, proporcionando comestibles, entrega a domicilio y Meals on Wheels para vecinos del condado Mecklenburg en necesidad, incluidos quienes regresan de la encarcelación que reconstruyen seguridad alimentaria. Algunas ubicaciones pueden requerir referencia.',
