    'd9000001-0093-4000-8000-000000000001',
    'Greensboro Urban Ministry — Food Pantry & Emergency Services',
    'Greensboro Urban Ministry provides emergency groceries, shelter referrals, and crisis assistance for Guilford County residents including returning citizens at the Gate City Boulevard food pantry Tuesday through Thursday. Guilford County residents can receive groceries every 14 days with photo ID—walk-in first-come-first-served during posted hours.',
    'Greensboro Urban Ministry ofrece comestibles de emergencia, referencias a refugios y asistencia en crisis para residentes del condado Guilford, incluidos quienes regresan de la encarcelación, en la despensa de Gate City Boulevard de martes a jueves. Los residentes pueden recibir comestibles cada 14 días con identificación con foto, sin cita por orden de llegada.',
