    'Urban Ministries of Wake County provides food and nutrition services, the Open Door Clinic for uninsured adults, and the Helen Wright Center shelter pathway for women experiencing homelessness in Wake County. Returning citizens access basic health and food support while navigating Coordinated Entry for longer-term housing through Wake County partners.',
