    'd9000001-0096-4000-8000-000000000001',
    'Salvation Army of Wake County — Emergency Assistance',
    'Salvation Army of Wake County — Emergency Assistance serves justice-involved adults and families rebuilding stability after incarceration in Wake County. The Salvation Army Wake County provides emergency food pantry, utility and rent assistance, clothing, and case management for low-income Wake County residents including returning citizens rebuilding stability. Social workers connect clients to Healing Transitions, StepUp Ministry, and NCWorks partners across the Triangle. Availability varies by season and donations; call ahead when possible to confirm clothing, hygiene kits, or furniture pickup hours. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Salvation Army of Wake County — Emergency Assistance sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Wake. La disponibilidad varía según la temporada y donaciones; llame cuando sea posible para confirmar horarios de ropa, kits de higiene o muebles. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
