  (
    'd9000001-0097-4000-8000-000000000001',
    'NC ePASS — Online Benefits Portal',
    'NC ePASS is North Carolina''s official online portal for applying for and managing Medicaid (Medical Assistance), Food and Nutrition Services (SNAP), Work First (TANF) cash assistance, and energy assistance. Justice-involved North Carolinians can apply for health coverage and food support after release; enhanced accounts allow online renewals and secure messaging with county caseworkers.',
    'NC ePASS es el portal en línea oficial de Carolina del Norte para solicitar y administrar Medicaid (Asistencia Médica), Servicios de Alimentos y Nutrición (SNAP), asistencia en efectivo Work First (TANF) y asistencia energética. Personas en reinserción pueden solicitar cobertura de salud y apoyo alimentario después de la liberación; cuentas mejoradas permiten renovaciones en línea.',
    'c1000001-0009-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
    NULL,
    NULL,
    '866-719-0141',
    'https://epass.nc.gov/',
    NULL,
    'Online 24/7',
    'NC residents meeting income and program requirements for Medicaid, SNAP, or TANF; criminal record generally not a barrier.',
    'Residentes de NC que cumplan requisitos de ingresos para Medicaid, SNAP o TANF; los antecedentes penales generalmente no son barrera.',
    'Apply online at epass.nc.gov; FNS interpreter line 866-719-0141.',
    'Solicite en epass.nc.gov; línea de intérprete FNS 866-719-0141.',
    ARRAY[]::TEXT[],
    'statewide',
    ARRAY['Medicaid application', 'SNAP enrollment', 'TANF/Work First application', 'Energy assistance', 'Online account management'],
