    'd9000001-0098-4000-8000-000000000001',
    'NC Medicaid Contact Center',
    'The NC Medicaid Contact Center helps residents apply for Medicaid and NC Health Choice health coverage by phone or mail, locate county Department of Social Services offices, and navigate Medicaid Expansion eligibility. Returning citizens can establish health coverage after release—criminal record is not a barrier to Medicaid eligibility in North Carolina.',
    'El Centro de Contacto de Medicaid de NC ayuda a residentes a solicitar Medicaid y cobertura NC Health Choice por teléfono o correo, localizar oficinas del Departamento de Servicios Sociales del condado y navegar elegibilidad de Expansión de Medicaid. Quienes regresan pueden establecer cobertura de salud; los antecedentes penales no son barrera para elegibilidad de Medicaid.',
