    'd9000001-0099-4000-8000-000000000001',
    'NC Food and Nutrition Services (SNAP) — Apply Online',
    'North Carolina Food and Nutrition Services (SNAP) provides monthly food assistance to eligible low-income households through county DSS offices and the ePASS online portal. Returning citizens can apply for SNAP after release; criminal drug felony restrictions have limited exceptions—contact your county DSS or apply online and complete the required interview.',
    'Los Servicios de Alimentos y Nutrición (SNAP) de Carolina del Norte proporcionan asistencia alimentaria mensual a hogares elegibles de bajos ingresos mediante oficinas DSS del condado y el portal ePASS. Quienes regresan pueden solicitar SNAP después de la liberación; restricciones por delitos de drogas tienen excepciones limitadas.',
