    'd9000001-0100-4000-8000-000000000001',
    'NC Work First (TANF) — Cash Assistance Program',
    'NC Work First is North Carolina''s Temporary Assistance for Needy Families program providing short-term cash assistance and work activities for eligible families with children through county Department of Social Services offices and ePASS. Eligibility rules exclude most childless adults; families reuniting after incarceration should contact their county DSS to assess Work First eligibility.',
    'NC Work First es el programa de Asistencia Temporal para Familias Necesitadas de Carolina del Norte que proporciona asistencia en efectivo a corto plazo y actividades laborales para familias elegibles con niños mediante oficinas DSS del condado y ePASS. Las reglas excluyen a la mayoría de adultos sin hijos; familias que se reúnen después de la encarcelación deben contactar su DSS del condado.',
    'c1000001-0009-4000-8000-000000000001',
