    'd9000001-0101-4000-8000-000000000001',
    'NC 211 — Statewide Information & Referral',
    'NC 211 is a free, confidential 24/7 information and referral service connecting North Carolina residents to health and human services including housing, food, utilities, employment, and crisis support across all 100 counties. United Way-supported specialists help callers—including returning citizens—find local programs by need and ZIP code in 170+ languages.',
    'NC 211 es un servicio gratuito y confidencial de información y referencia 24/7 que conecta a residentes de Carolina del Norte con servicios de salud y humanos incluyendo vivienda, alimentos, servicios públicos, empleo y apoyo en crisis en los 100 condados. Especialistas apoyados por United Way ayudan a quienes llaman, incluidos quienes regresan, a encontrar programas locales en más de 170 idiomas.',
    'c1000001-0001-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
    NULL,
    NULL,
    '888-892-1162',
    'https://nc211.org/',
