  (
    'd9000001-0102-4000-8000-000000000001',
    'Recidivism Reduction Hotline — NC Reentry Resource Navigation',
    'The Recidivism Reduction Hotline connects justice-involved North Carolinians and their families to reentry resources across every county through a database of more than 800 verified entries staffed by certified community health workers with lived experience of incarceration. Operated by Recidivism Reduction Educational Program Services, the hotline runs weekdays 9:00 a.m.–5:00 p.m.',
    'La Línea Directa de Reducción de Reincidencia conecta a carolinenses con antecedentes penales y sus familias con recursos de reinserción en todos los condados mediante una base de datos de más de 800 entradas verificadas atendida por trabajadores de salud comunitaria certificados con experiencia de encarcelación. Operada por Recidivism Reduction Educational Program Services, lun–vie 9:00 a.m.–5:00 p.m.',
    'c1000001-0001-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
