  (
    'd9000001-0103-4000-8000-000000000001',
    'NCDMV — Driver License and ID Card Services',
    'NCDMV — Driver License and ID Card Services serves justice-involved adults and families rebuilding stability after incarceration in throughout North Carolina. The NC Division of Motor Vehicles issues REAL ID-compliant driver licenses and identification cards required for employment, housing applications, and banking after release. Returning citizens can request driving records via myNCDMV, resolve suspensions, and schedule in-person reinstatement visits at driver license offices statewide. Fees, proof of identity, and residency documents apply; reentry resources and legal aid partners often help gather required paperwork. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'NCDMV — Driver License and ID Card Services sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en toda Carolina del Norte. Aplican tarifas, prueba de identidad y documentos de residencia; recursos de reinserción y aliados legales suelen ayudar a reunir el papeleo requerido. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0008-4000-8000-000000000001',
    'North Carolina',
    'Statewide',
    NULL,
    NULL,
    '919-715-7000',
    'https://www.ncdot.gov/dmv/',
