    'Residentes de NC que cumplan requisitos de identidad y residencia de DMV; aplican tarifas para licencias e identificaciones.',
    'Driving records at ncdot.gov/dmv; myNCDMV online services.',
    'Registros de conducción en ncdot.gov/dmv; servicios en línea myNCDMV.',
