    'd9000001-0104-4000-8000-000000000001',
    'NCDAC — In-Custody Driver License Restoration Clinics',
    'The NC Department of Adult Correction partners with law schools and legal aid organizations to hold driver license restoration clinics inside prisons, helping individuals review DMV records and receive advice letters before release. Clinics with Duke Law, Campbell Law, and Pisgah Legal Services address FTA and court-debt suspensions that block employment and reentry mobility.',
    'El Departamento de Corrección para Adultos de NC colabora con facultades de derecho y organizaciones de ayuda legal para realizar clínicas de restauración de licencias de conducir dentro de prisiones, ayudando a personas a revisar registros del DMV y recibir cartas de orientación antes de la liberación. Clínicas con Duke Law, Campbell Law y Pisgah Legal Services abordan suspensiones por incomparecencia y deudas judiciales.',
