    'd9000001-0105-4000-8000-000000000001',
    'NC Vital Records — Birth Certificate Requests',
    'NC Vital Records — Birth Certificate Requests serves justice-involved adults and families rebuilding stability after incarceration in throughout North Carolina. NC Vital Records through NCDHHS issues certified birth certificates needed for DMV ID, employment verification, and benefits applications after incarceration. Returning citizens can order certificates online, by mail, or through county register of deeds offices with valid identification and applicable fees. Fees, proof of identity, and residency documents apply; reentry resources and legal aid partners often help gather required paperwork. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'NC Vital Records — Birth Certificate Requests sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en toda Carolina del Norte. Aplican tarifas, prueba de identidad y documentos de residencia; recursos de reinserción y aliados legales suelen ayudar a reunir el papeleo requerido. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
