    'SouthLight Healthcare — Peer Support Services',
    'SouthLight Healthcare Certified Peer Support Specialists with shared lived experience guide individuals in recovery from mental health and substance use disorders across Wake, Durham, Johnston, and Wilson counties, including justice-involved participants referred from probation, courts, and treatment programs. Non-clinical peer coaching supports sobriety maintenance and reentry barrier navigation.',
