    'd9000001-0107-4000-8000-000000000001',
    'NC Certified Peer Support Specialist Program — NCDHHS',
    'NC Certified Peer Support Specialist Program — NCDHHS serves justice-involved adults and families rebuilding stability after incarceration in throughout North Carolina. The NCDHHS Certified Peer Support Specialist program trains and certifies individuals with 18+ months of recovery from mental illness or substance use disorder to provide Medicaid-billable peer support services statewide, including reentry transition support for people leaving incarceration through LME/MCO provider networks. Peer specialists with lived experience offer mentoring and recovery support; certification requirements vary by resource. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'NC Certified Peer Support Specialist Program — NCDHHS sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en toda Carolina del Norte. Especialistas pares con experiencia vivida ofrecen mentoría y apoyo en recuperación; los requisitos de certificación varían según el recurso. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
