    'd9000001-0108-4000-8000-000000000001',
    'NC Council for Recovery — Peer Recovery Supports',
    'NC Council for Recovery — Peer Recovery Supports serves justice-involved adults and families rebuilding stability after incarceration in throughout North Carolina. The NC Council for Recovery (formerly NC Council on Substance Abuse) provides peer recovery support, advocacy, and community education for individuals in recovery from substance use disorders across North Carolina, including justice-involved participants in accountability and drug treatment courts seeking non-clinical peer mentorship. Peer specialists with lived experience offer mentoring and recovery support; certification requirements vary by resource. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'NC Council for Recovery — Peer Recovery Supports sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en en toda Carolina del Norte. Especialistas pares con experiencia vivida ofrecen mentoría y apoyo en recuperación; los requisitos de certificación varían según el recurso. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
