    'd9000001-0109-4000-8000-000000000001',
    'TROSA — Substance Use Disorder Treatment Program',
    'TROSA is a state-licensed multi-year voluntary substance use disorder treatment program providing evidence-based behavioral therapy, vocational training, medical care, and psychiatric services at no charge to residents including justice-involved adults referred by courts and probation. Graduates show high recovery and employment rates with low one-year recidivism.',
    'TROSA es un programa voluntario de tratamiento de trastornos por uso de sustancias de varios años con licencia estatal que ofrece terapia conductual basada en evidencia, capacitación vocacional, atención médica y servicios psiquiátricos sin costo, incluidos adultos con antecedentes penales referidos por tribunales y libertad condicional. Los graduados muestran altas tasas de recuperación y empleo.',
    'c1000001-0005-4000-8000-000000000001',
    'North Carolina',
    'Durham',
    'Durham',
    '1820 James Street',
    '919-419-1059',
    'https://trosainc.org/',
    'admissions@trosainc.org',
    'Admissions business hours',
    'Adults with SUD seeking long-term residential treatment; call admissions for interview.',
    'Adultos con TUS que buscan tratamiento residencial a largo plazo; llame a admisiones para entrevista.',
    'Toll-free 833-408-7672; campuses in Durham and Winston-Salem.',
    'Línea gratuita 833-408-7672; campus en Durham y Winston-Salem.',
    ARRAY['Durham', 'Wake', 'Orange', 'Forsyth'],
