    'd9000001-0110-4000-8000-000000000001',
    'Healing Transitions — Non-Medical Detox Services',
    'Healing Transitions provides 24/7 non-medical detox and emergency shelter entry points for Wake County adults with substance use disorders, including justice-involved residents seeking immediate stabilization before entering the long-term recovery program. Low-barrier access with peer support—call men''s detox 919-838-9848 or women''s 919-865-2558.',
    'Healing Transitions ofrece desintoxicación no médica 24/7 y puntos de entrada a refugio de emergencia para adultos del condado Wake con trastornos por uso de sustancias, incluidos residentes con antecedentes penales que buscan estabilización inmediata. Acceso de baja barrera con apoyo entre pares; desintoxicación hombres 919-838-9848 o mujeres 919-865-2558.',
