  (
    'd9000001-0111-4000-8000-000000000001',
    'Durham Recovery Response Center',
    'Durham Recovery Response Center is a statewide or regional referral resource for North Carolinians affected by the criminal justice system. The Durham Recovery Response Center operated through Lincoln Community Health Center provides crisis stabilization and substance use disorder assessment for Durham County residents including justice-involved individuals needing immediate behavioral health intervention before referral to TROSA, SouthLight, or Lincoln CHC ongoing care. Users can search by location, service type, or need to find active providers in Durham County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'Durham Recovery Response Center es un recurso de referencia estatal o regional para carolinenses del norte afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Durham. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
    'c1000001-0005-4000-8000-000000000001',
    'North Carolina',
    'Durham',
    'Durham',
    '309 Crutchfield Street',
    '919-797-1941',
    'https://lincolnchc.org/',
    NULL,
    'Contact for crisis hours',
    'Durham County residents in behavioral health or SUD crisis; walk-in or referral.',
    'Residentes del condado Durham en crisis de salud conductual o TUS; sin cita o referencia.',
    'Part of Lincoln CHC network; connects to Durham LRC partners.',
    'Parte de la red Lincoln CHC; conecta con aliados del LRC de Durham.',
    ARRAY['Durham'],
    'single',
    ARRAY['Crisis services', 'SUD assessment', 'Behavioral health services', 'Partner referrals'],
    ARRAY['durham', 'substance-use-treatment', 'crisis', 'reentry', 'north-carolina'],
