    'CATS Special Transportation Service (STS)',
    'Charlotte Area Transit System Special Transportation Service provides ADA-compliant paratransit for Mecklenburg County residents whose disabilities prevent use of fixed-route buses, including returning citizens with mobility limitations needing rides to work, probation reporting, and medical appointments. Apply for eligibility certification at 833-656-7699 before scheduling rides.',
    'El Servicio de Transporte Especial de CATS proporciona paratransit compatible con ADA para residentes del condado Mecklenburg cuyas discapacidades impiden usar autobuses de ruta fija, incluidos quienes regresan con limitaciones de movilidad que necesitan transporte al trabajo, reportes de libertad condicional y citas médicas. Solicite certificación de elegibilidad al 833-656-7699.',
