    'Center for Community Transitions Families Doing Time supports children and caregivers affected by parental incarceration through support groups, mentoring, and family reunification planning at the Newell Presbyterian Church education building in Charlotte. The program helps families maintain bonds during incarceration and navigate reentry reunification.',
