  (
    'd9000001-0115-4000-8000-000000000001',
    'StepUp Ministry — Real World Youth Program',
    'StepUp Ministry — Real World Youth Program serves justice-involved adults and families rebuilding stability after incarceration in Wake County. StepUp Ministry Real World program helps teens ages 14–22 transition to adulthood through weekly mentoring, social-emotional learning, and case management for Wake County youth including those affected by parental incarceration or reentry family reunification. Parental involvement not required for teens 14–22 in the Real World track. Family resources may require participation in treatment or parenting classes; custody status affects some reunification services. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'StepUp Ministry — Real World Youth Program sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Wake. Los recursos familiares pueden requerir participación en tratamiento o clases de crianza; el estado de custodia afecta algunos servicios de reunificación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0011-4000-8000-000000000001',
