    'd9000001-0116-4000-8000-000000000001',
    'Second Harvest Food Bank of Southeast NC',
    'Second Harvest Food Bank of Southeast North Carolina distributes food through partner agencies across Bladen, Cumberland, Duplin, Harnett, Hoke, Robeson, and Sampson counties, serving low-income residents including returning citizens in rural Sandhills and southeastern communities. The Fayetteville warehouse connects neighbors to pantries, mobile distributions, and SNAP enrollment partners. Regional food bank—not direct walk-in pantry.',
    'Second Harvest Food Bank del sureste de Carolina del Norte distribuye alimentos a través de agencias aliadas en los condados Bladen, Cumberland, Duplin, Harnett, Hoke, Robeson y Sampson, sirviendo a residentes de bajos ingresos incluidos ciudadanos que regresan en comunidades rurales. El almacén de Fayetteville conecta a vecinos con despensas y distribuciones móviles.',
    'c1000001-0007-4000-8000-000000000001',
    'North Carolina',
    'Cumberland',
    'Fayetteville',
