    'Open to residents in seven-county service area needing food assistance through partner pantries.',
    'Abierto a residentes en el área de servicio de siete condados que necesitan asistencia alimentaria mediante despensas aliadas.',
    'Find partner pantries at secondharvestnc.org; serves Sandhills and southeastern NC counties.',
    'Encuentre despensas aliadas en secondharvestnc.org; sirve condados Sandhills y sureste de NC.',
