  (
    'd9000001-0117-4000-8000-000000000001',
    'Food Bank of the Albemarle — Northeastern NC',
    'Food Bank of the Albemarle serves northeastern North Carolina including Bertie, Camden, Chowan, Currituck, Dare, Gates, Hertford, Hyde, Martin, Northampton, Pasquotank, Perquimans, Tyrrell, and Washington counties through a network of partner food pantries and mobile distributions. Justice-involved adults in rural northeastern counties access emergency food through partner agencies listed on the food bank website.',
