  (
    'd9000001-0123-4000-8000-000000000001',
    'Rutherford Health — FQHC Network',
    'Rutherford Health — FQHC Network serves justice-involved adults and families rebuilding stability after incarceration in Rutherford, McDowell, Polk, and Cleveland counties. Rutherford Health operates Federally Qualified Health Center clinics serving Rutherford, McDowell, and Polk counties in western North Carolina foothills, providing primary care, dental, and behavioral health on a sliding-fee scale for uninsured and Medicaid patients including justice-involved adults in rural communities. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Rutherford Health — FQHC Network sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en los condados Rutherford, McDowell, Polk y Cleveland. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0004-4000-8000-000000000001',
    'North Carolina',
    'Rutherford',
