    'Residentes sin seguro y de bajos ingresos en condados de servicio Rutherford Health; tarifa móvil disponible.',
    'Call 828-245-0620 for appointments; Forest City and Spindale clinic locations.',
    'Llame al 828-245-0620 para citas; ubicaciones de clínicas Forest City y Spindale.',
