    'd9000001-0126-4000-8000-000000000001',
    'Raleigh Rescue Mission — New Life Plan Transitional Housing',
    'Raleigh Rescue Mission provides transitional housing and wraparound services through its New Life Plan for homeless men, women, and families in Wake County including returning citizens rebuilding stability after incarceration. The phased program offers shelter, meals, counseling, vocational training, and employment support leading to independent housing. Commitment to the multi-month New Life Plan required—not walk-in emergency shelter without intake.',
    'Raleigh Rescue Mission ofrece vivienda transicional y servicios integrales a través de su Plan Nueva Vida para hombres, mujeres y familias sin hogar en el condado Wake, incluidos ciudadanos que regresan que reconstruyen estabilidad después de la encarcelación. El programa por fases ofrece refugio, comidas, consejería, capacitación vocacional y apoyo laboral hacia vivienda independiente. Se requiere compromiso con el plan de varios meses.',
    'c1000001-0002-4000-8000-000000000001',
    'North Carolina',
    'Wake',
    'Raleigh',
    '314 East Hargett Street',
    '919-828-9014',
    'https://www.raleighrescue.org',
