    'Residential program; contact for intake hours',
    'Homeless adults in Wake County willing to commit to the New Life Plan; justice-involved participants welcome per program policy.',
    'Adultos sin hogar en el condado Wake dispuestos a comprometerse con el Plan Nueva Vida; participantes con antecedentes penales bienvenidos según política.',
    'Email MensProgram@raleighrescue.org or WomensProgram@raleighrescue.org; pairs with Wake LRC and NCWorks Capital Area.',
    'Envíe correo a MensProgram@raleighrescue.org o WomensProgram@raleighrescue.org; se vincula con LRC de Wake y NCWorks.',
