    'Homeward Bound del oeste de Carolina del Norte ofrece vivienda de apoyo permanente, realojamiento rápido y prevención de la falta de vivienda para adultos sin hogar en el condado Buncombe, incluidos ciudadanos que regresan de la cárcel o programas de tratamiento. El Centro Diurno AHOPE ofrece duchas, recepción de correo y evaluaciones de vivienda.',
