  (
    'd9000001-0131-4000-8000-000000000001',
    'CASA — Transitional Living Program',
    'CASA (Community Alternatives for Supportive Abodes) provides affordable and supportive housing including transitional living for low-income adults in Durham and Orange counties, serving justice-involved tenants through permanent supportive housing and rapid rehousing partnerships. Property management and supportive services help returning citizens maintain stable leases and connect to local reentry resources. Housing provider—not emergency walk-in shelter.',
    'CASA (Alternativas Comunitarias para Viviendas de Apoyo) ofrece vivienda asequible y de apoyo incluyendo vida transicional para adultos de bajos ingresos en los condados Durham y Orange, sirviendo a inquilinos con antecedentes penales mediante vivienda de apoyo permanente. La administración de propiedades ayuda a quienes regresan a mantener arrendamientos estables.',
