    'Family Promise of the Triangle provides emergency shelter, case management, and rehousing assistance for homeless families in Wake, Durham, and Orange counties including parents returning from incarceration seeking reunification with children. Congregation-based shelter network and stabilization services connect families to employment, childcare, and permanent housing. Family-focused program—not single-adult men''s shelter.',
