    'd9000001-0168-4000-8000-000000000001',
    'NC Peer Warmline — Promise Resource Network',
    'The NC Peer Warmline at 1-855-PEERS-NC is a free 24/7 service staffed by Certified Peer Support Specialists with lived experience in mental health and substance use recovery, including justice-involved North Carolinians navigating reentry challenges. Operated by Promise Resource Network, the warmline offers non-crisis support by phone, text, and chat—not a substitute for 988 emergency services.',
