    'd9000001-0171-4000-8000-000000000001',
    'NCWorks Career Center — Anson County',
    'NCWorks Career Center Anson County at the Lockhart-Taylor Center in Wadesboro connects job seekers including justice-involved adults from Anson County Jail and NCDAC custody to WIOA-funded training, resume assistance, fair-chance employment navigation, and NCWorks online job matching. Staff link returning citizens to Atrium Health Anson, Anson Crisis Ministry, and regional reentry partners in the Charlotte metro Sandhills fringe. Free core career services—not emergency cash or housing placement.',
    'NCWorks Career Center del condado Anson en el Lockhart-Taylor Center de Wadesboro conecta buscadores de empleo incluidos adultos con antecedentes penales de la cárcel del condado Anson y custodia NCDAC con capacitación WIOA, ayuda con currículum y navegación de empleo de segunda oportunidad. El personal vincula a quienes regresan con Atrium Health Anson y Anson Crisis Ministry. Servicios básicos de carrera gratuitos.',
