    'Atrium Health Anson es un hospital de 15 camas y hogar médico en Wadesboro que ofrece atención de emergencia 24/7, atención primaria, salud conductual y referencias de especialidad para residentes del condado Anson incluidos pacientes sin seguro y Medicaid como ciudadanos que regresan. Carolinas Primary Care en el sitio coordina manejo de enfermedades crónicas y alcance comunitario.',
