    'd9000001-0173-4000-8000-000000000001',
    'Anson Crisis Ministry — Food Bank',
    'Anson Crisis Ministry operates a food bank in Wadesboro distributing groceries, produce, and nutrition support to low-income Anson County households including returning citizens reestablishing food security after incarceration. Registered clients may receive food up to twice monthly; mobile pantry events rotate among partner churches in Anson and eastern Union counties. Direct food assistance—not a statewide hotline.',
    'Anson Crisis Ministry opera un banco de alimentos en Wadesboro distribuyendo comestibles y apoyo nutricional a hogares de bajos ingresos del condado Anson incluidos ciudadanos que regresan que reestablecen seguridad alimentaria. Clientes registrados pueden recibir alimentos hasta dos veces al mes; despensas móviles rotan entre iglesias aliadas.',
