    'NCWorks Career Center Craven en New Bern brinda servicios de empleo gratuitos para adultos con antecedentes penales en los condados Craven, Jones y Pamlico incluyendo coaching de currículum, apoyo a veteranos y referencias de capacitación WIOA. El personal coordina con Craven Community College y el Centro de Salud Comunitario del condado Craven.',
