    'd9000001-0234-4000-8000-000000000001',
    'ECU Health North Hospital (serves Halifax County)',
    'ECU Health North Hospital (serves Halifax County) is a statewide or regional referral resource for North Carolinians affected by the criminal justice system. ECU Health North Hospital provides emergency, primary care referrals, and community health access for Halifax County residents including uninsured and Medicaid patients such as returning citizens establishing medical care after release from Halifax County Detention Center or VADOC facilities. Users can search by location, service type, or need to find active providers in Halifax County. Specialists or online tools help match people to housing, treatment, employment, legal aid, or benefits resources operated by other organizations. This entry describes a navigation hub—staff here do not replace direct services at partner agencies.',
    'ECU Health North Hospital (serves Halifax County) es un recurso de referencia estatal o regional para carolinenses del norte afectados por el sistema de justicia penal. Los usuarios pueden buscar por ubicación, tipo de servicio o necesidad para encontrar proveedores activos en condado de Halifax. Herramientas en línea o especialistas ayudan a conectar con vivienda, tratamiento, empleo, asistencia legal o beneficios operados por otras organizaciones. Esta entrada describe un centro de navegación—el personal no reemplaza servicios directos en agencias aliadas.',
    'c1000001-0004-4000-8000-000000000001',
    'North Carolina',
