    'd9000001-0237-4000-8000-000000000001',
    'Atrium Health Richmond (serves Richmond County)',
    'Atrium Health Richmond (serves Richmond County) serves justice-involved adults and families rebuilding stability after incarceration in Richmond County. Atrium Health Richmond provides emergency and outpatient services for Richmond County residents including justice-involved adults establishing medical care after release from Richmond County Jail. Services are available on a sliding fee or Medicaid basis for eligible patients; bring ID and release paperwork when establishing care after incarceration. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Atrium Health Richmond (serves Richmond County) sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Richmond. Los servicios están disponibles con tarifa móvil o Medicaid para pacientes elegibles; lleve identificación y documentos de liberación al establecer atención después de la encarcelación. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
