  (
    'd9000001-0241-4000-8000-000000000001',
    'Alamance County DSS — Benefits & Family Support',
    'Alamance County DSS — Benefits & Family Support serves justice-involved adults and families rebuilding stability after incarceration in Alamance County. Alamance County Department of Social Services office in Burlington processes SNAP, Medicaid, NC Health Choice, and Work First applications for North Carolina residents including returning citizens reestablishing food and health benefits after release from Alamance County Jail or NCDAC custody. Bring proof of identity, income, and release or residency documents when applying at a county office or online portal. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Alamance County DSS — Benefits & Family Support sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Alamance. Lleve prueba de identidad, ingresos y documentos de liberación o residencia al solicitar en una oficina del condado o portal en línea. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0009-4000-8000-000000000001',
    'North Carolina',
    'Alamance',
    'Burlington',
    '319 N. Graham-Hopedale Road, Suite C, Burlington, NC 27217',
    '336-570-6532',
    'https://www.ncdhhs.gov/divisions/social-services/local-dss-directory',
    NULL,
    'Typically Monday–Friday business hours; call ahead',
    'Alamance County residents meeting income and household-size requirements for SNAP, Medicaid, and Work First; criminal record generally not a barrier.',
    'Residentes del condado Alamance que cumplan requisitos de ingresos para SNAP, Medicaid y Work First; los antecedentes penales generalmente no son barrera.',
    'Apply online at epass.nc.gov or visit the county DSS office; call 1-866-719-0141 for NC FAST help.',
    'Solicite en epass.nc.gov o visite la oficina DSS del condado; llame al 1-866-719-0141 para ayuda NC FAST.',
    ARRAY['Alamance'],
