    'Yancey County DSS — Benefits & Family Support serves justice-involved adults and families rebuilding stability after incarceration in Yancey County. Yancey County Department of Social Services office in Burnsville processes SNAP, Medicaid, NC Health Choice, and Work First applications for North Carolina residents including returning citizens reestablishing food and health benefits after release from Yancey County Jail or NCDAC custody. Bring proof of identity, income, and release or residency documents when applying at a county office or online portal. Contact this resource to confirm current intake steps, required documents, and whether walk-ins or referrals are accepted.',
    'Yancey County DSS — Benefits & Family Support sirve a adultos con antecedentes penales y familias que reconstruyen estabilidad después de la encarcelación en condado de Yancey. Lleve prueba de identidad, ingresos y documentos de liberación o residencia al solicitar en una oficina del condado o portal en línea. Contacte este recurso para confirmar pasos de admisión, documentos requeridos y si aceptan visitas sin cita o referencias.',
    'c1000001-0009-4000-8000-000000000001',
