    NULL,
    'Typically Monday–Friday business hours; call ahead',
    'Yancey County residents meeting income and household-size requirements for SNAP, Medicaid, and Work First; criminal record generally not a barrier.',
    'Residentes del condado Yancey que cumplan requisitos de ingresos para SNAP, Medicaid y Work First; los antecedentes penales generalmente no son barrera.',
    'Apply online at epass.nc.gov or visit the county DSS office; call 1-866-719-0141 for NC FAST help.',
